package org.apache.commons.lang;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.Collection;
import java.util.Iterator;
import java.util.List;
import java.util.Locale;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class StringUtils_containsIgnoreCase_TriageGen1Test {

    @Test
    public void testContainsIgnoreCase_NullStr() {
        assertFalse(StringUtils.containsIgnoreCase(null, "abc"));
    }

    @Test
    public void testContainsIgnoreCase_NullSearchStr() {
        assertFalse(StringUtils.containsIgnoreCase("abc", null));
    }

    @Test
    public void testContainsIgnoreCase_BothNull() {
        assertFalse(StringUtils.containsIgnoreCase(null, null));
    }

    @Test
    public void testContainsIgnoreCase_EmptySearchStr() {
        // If searchStr is empty, length is 0, max is str.length(), loop runs once at i=0
        // regionMatches(false, 0, "", 0, 0) is true
        assertTrue(StringUtils.containsIgnoreCase("abc", ""));
        assertTrue(StringUtils.containsIgnoreCase("", ""));
    }

    @Test
    public void testContainsIgnoreCase_EmptyStr() {
        assertFalse(StringUtils.containsIgnoreCase("", "abc"));
    }

    @Test
    public void testContainsIgnoreCase_ExactMatchSameCase() {
        assertTrue(StringUtils.containsIgnoreCase("HelloWorld", "HelloWorld"));
    }

    @Test
    public void testContainsIgnoreCase_ExactMatchDifferentCase() {
        assertTrue(StringUtils.containsIgnoreCase("HelloWorld", "helloworld"));
        assertTrue(StringUtils.containsIgnoreCase("HelloWorld", "HELLOWORLD"));
    }

    @Test
    public void testContainsIgnoreCase_SubstringMatch() {
        assertTrue(StringUtils.containsIgnoreCase("The quick brown fox", "QUICK"));
        assertTrue(StringUtils.containsIgnoreCase("The quick brown fox", "fox"));
    }

    @Test
    public void testContainsIgnoreCase_NoMatch() {
        assertFalse(StringUtils.containsIgnoreCase("abc", "def"));
        assertFalse(StringUtils.containsIgnoreCase("abc", "abcd"));
    }

    @Test
    public void testContainsIgnoreCase_SpecialCharacters() {
        assertTrue(StringUtils.containsIgnoreCase("!@#$%^&*()", "@#$"));
        assertFalse(StringUtils.containsIgnoreCase("!@#$%^&*()", "@#$z"));
    }

    @Test
    public void testContainsIgnoreCase_BoundaryCase_SearchStrLongerThanStr() {
        // max = str.length() - len will be negative, loop won't execute
        assertFalse(StringUtils.containsIgnoreCase("abc", "abcdef"));
    }

    @Test
    public void testContainsIgnoreCase_BoundaryCase_EqualLength() {
        assertTrue(StringUtils.containsIgnoreCase("abc", "ABC"));
        assertFalse(StringUtils.containsIgnoreCase("abc", "abd"));
    }
}
